CREATE TABLE wallets (id int PRIMARY KEY, balance_cents bigint)
  WITH (autovacuum_enabled = off);
INSERT INTO wallets VALUES (1, 50000), (2, 50000), (3, 50000);
SELECT ctid, xmin, xmax, * FROM wallets;

UPDATE wallets SET balance_cents = balance_cents - 2500 WHERE id = 2;
SELECT ctid, xmin, xmax, * FROM wallets;
SELECT lp, t_xmin, t_xmax, t_ctid FROM heap_page_items(get_raw_page('wallets', 0));

-- terminal 1: a slow transfer, left open
BEGIN;
UPDATE wallets SET balance_cents = balance_cents - 1000 WHERE id = 1;
SELECT pg_current_xact_id() AS writer;

-- terminal 2: a new customer's wallet, then a report
INSERT INTO wallets VALUES (4, 50000);
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT pg_current_snapshot();
SELECT id, balance_cents FROM wallets ORDER BY id;

-- terminal 1
COMMIT;

-- terminal 2
SELECT id, balance_cents FROM wallets ORDER BY id;
SELECT lp, t_xmin, t_xmax, t_ctid FROM heap_page_items(get_raw_page('wallets', 0));
COMMIT;
SELECT id, balance_cents FROM wallets ORDER BY id;

-- terminal 1: transfer A, left open
BEGIN;
UPDATE wallets SET balance_cents = balance_cents - 700 WHERE id = 3;

-- terminal 2: refund B under REPEATABLE READ
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT balance_cents FROM wallets WHERE id = 3;
SELECT lp, t_xmin, t_xmax FROM heap_page_items(get_raw_page('wallets', 0)) WHERE lp = 3;
UPDATE wallets SET balance_cents = balance_cents + 100 WHERE id = 3;   -- waits

-- terminal 1
COMMIT;

-- terminal 2: the UPDATE has failed; end the transaction
ROLLBACK;

-- the same race with READ COMMITTED, the default, in terminal 2
-- terminal 1
BEGIN;
UPDATE wallets SET balance_cents = balance_cents - 700 WHERE id = 3;
-- terminal 2
BEGIN;
UPDATE wallets SET balance_cents = balance_cents + 100 WHERE id = 3 RETURNING balance_cents;   -- waits
-- terminal 1
COMMIT;
-- terminal 2
COMMIT;

-- terminal 1: a report that stays open
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(balance_cents) FROM wallets;

-- terminal 2: make 20,000 dead versions, then vacuum
CREATE TABLE settlements (id int PRIMARY KEY, amount_cents bigint)
  WITH (autovacuum_enabled = off);
INSERT INTO settlements SELECT g, 1000 FROM generate_series(1, 10000) g;
SELECT pg_relation_size('settlements') / 8192 AS pages;
UPDATE settlements SET amount_cents = amount_cents + 1;
UPDATE settlements SET amount_cents = amount_cents + 1;
SELECT pg_relation_size('settlements') / 8192 AS pages;
SELECT pg_stat_force_next_flush();
SELECT n_live_tup, n_dead_tup FROM pg_stat_user_tables WHERE relname = 'settlements';
VACUUM (VERBOSE) settlements;

-- terminal 1
COMMIT;

-- terminal 2: vacuum again, then freeze
VACUUM (VERBOSE) settlements;
SELECT pg_relation_size('settlements') / 8192 AS pages;
SELECT count(DISTINCT (ctid::text::point)[0]) AS pages_with_rows FROM settlements;
SELECT age(relfrozenxid) FROM pg_class WHERE relname = 'settlements';
VACUUM (FREEZE) settlements;
SELECT age(relfrozenxid) FROM pg_class WHERE relname = 'settlements';
SELECT t_xmin, combined_flags
FROM heap_page_items(get_raw_page('settlements', 162)),
     LATERAL heap_tuple_infomask_flags(t_infomask, t_infomask2)
WHERE lp_flags = 1 LIMIT 1;
SHOW autovacuum_freeze_max_age;

# terminal 1, inside mysql
START TRANSACTION WITH CONSISTENT SNAPSHOT;
SELECT sum(amount_cents) AS total FROM settlements;

# terminal 2: 1,000 transactions, one UPDATE each
for i in $(seq 1 1000); do
  echo "UPDATE settlements SET amount_cents = amount_cents + 1 WHERE id = $i;"
done | docker compose -f env/mysql.yml exec -T db mysql course
docker compose -f env/mysql.yml exec db mysql course -e "
  SELECT name, count FROM information_schema.INNODB_METRICS WHERE name = 'trx_rseg_history_len';
  SELECT sum(amount_cents) AS total FROM settlements;"

# terminal 1
SELECT sum(amount_cents) AS total FROM settlements;
COMMIT;

# terminal 2, a few times over the next 30 seconds
docker compose -f env/mysql.yml exec db mysql course -e "
  SELECT name, count FROM information_schema.INNODB_METRICS WHERE name = 'trx_rseg_history_len';"

