fun sees(s: Snapshot, xid: Long): Boolean {
    if (xid == s.owner) return true              // my own changes
    if (xid >= s.xmax) return false              // not finished when I took the snapshot
    if (xid in s.active) return false            // running when I took it
    return status(xid) == TxStatus.COMMITTED     // finished: visible only if it committed
}

fun isVisible(v: Version, s: Snapshot): Boolean =
    sees(s, v.xmin) && !(v.xmax != 0L && sees(s, v.xmax))

// The `xid in s.active` and `xid >= s.xmax` checks: a transaction that was running when the
// snapshot was taken stays invisible after it commits, so reading again gives the same answer.
